import numpy as np

try:
    from pyDOE2 import lhs as _lhs
except ImportError:
    try:
        from scipy.stats import qmc
        def _lhs(n_samples, n_dim):
            return qmc.LatinHypercube(d=n_dim).random(n=n_samples)
    except ImportError:
        raise ImportError("pyDOE2 or scipy required")

class Optimizer:
    def __init__(self, budget: int, dim: int):
        self.budget = budget
        self.dim = dim
        self.evals = 0
        self.best_f = float('inf')
        self.best_x = np.random.uniform(-1.0, 1.0, dim)
        self.pop_size = 32
        self.rng = np.random.default_rng()
        self.F = 0.5
        self.CR = 0.9
        self.success_F = []
        self.success_CR = []
        self.ls_steps = 10
        self.top_k = 4
        self.stagnation_limit = 6

    def _levy(self, size):
        u = self.rng.normal(0, 1, size)
        v = self.rng.normal(0, 1, size)
        return u / (np.abs(v) ** (1/1.5))

    def _cauchy(self, size):
        return self.rng.standard_cauchy(size)

    def _evaluate(self, x, func):
        if self.evals >= self.budget:
            return float('inf')
        x_clip = np.clip(x, -1.0, 1.0)
        f = func(x_clip)
        self.evals += 1
        if f < self.best_f:
            self.best_f = f
            self.best_x = x_clip.copy()
        return f

    def _gradient_adaptive_search(self, x, func, grad_func):
        if self.evals >= self.budget or grad_func is None:
            return x
        x_curr = np.clip(x, -1.0, 1.0)
        f_curr = self._evaluate(x_curr, func)
        step = 0.2
        alpha = 1e-4
        for _ in range(self.ls_steps):
            if self.evals >= self.budget:
                break
            grad_18 = grad_func(x_curr)
            grad_full = np.zeros(self.dim)
            grad_full[:18] = grad_18
            g_norm = np.linalg.norm(grad_full) + 1e-8

            # Armijo-compatible step with gradient scaling
            adaptive_step = step / (1.0 + 0.5 * g_norm)
            perturbation = np.zeros(self.dim)
            perturbation[:18] = self.rng.normal(0, 0.01, 18)
            perturbation[18:] = self.rng.normal(0, 0.03, 6)

            x_new = x_curr - adaptive_step * grad_full + perturbation
            x_new = np.clip(x_new, -1.0, 1.0)
            f_new = self._evaluate(x_new, func)

            if f_new < f_curr + alpha * adaptive_step * g_norm:
                x_curr = x_new
                f_curr = f_new
                step = np.clip(step * 1.5, 0.01, 1.0)
            else:
                step *= 0.5
        return x_curr

    def __call__(self, func, grad_func=None):
        if self.evals >= self.budget:
            return self.best_f, self.best_x

        pop = np.clip(_lhs(n_samples=self.pop_size, n_dim=self.dim) * 2.0 - 1.0, -1.0, 1.0)
        fitness = np.array([self._evaluate(pop[i], func) for i in range(self.pop_size)])
        if self.evals >= self.budget:
            return self.best_f, self.best_x

        max_gen = max(3, self.budget // self.pop_size)
        idxs = np.arange(self.pop_size)
        prev_best = self.best_f
        stagnation = 0

        for gen in range(max_gen):
            if self.evals >= self.budget:
                break

            # jADE historical parameter tracking
            if self.success_F:
                self.F = np.clip(self.rng.choice(self.success_F), 0.1, 1.0)
                self.CR = np.clip(self.rng.choice(self.success_CR), 0.0, 1.0)

            valid_idx = np.where(fitness < np.inf)[0]
            if len(valid_idx) == 0:
                valid_idx = np.arange(self.pop_size)
            best_idx = valid_idx[np.argmin(fitness[valid_idx])]
            x_best = pop[best_idx]

            new_pop = pop.copy()
            new_fit = fitness.copy()

            for i in range(self.pop_size):
                if self.evals >= self.budget:
                    break

                others = np.delete(idxs, i)
                r1, r2, r3 = self.rng.choice(others, 3, replace=False)

                # Gradient-aware mutation scaling
                g_scale = 1.0
                if grad_func is not None and self.evals < self.budget:
                    try:
                        grad_18 = grad_func(x_best)
                        g_scale = 1.0 / (1.0 + 0.5 * np.linalg.norm(grad_18))
                    except:
                        pass

                # Hybrid mutation with gradient modulation
                op = self.rng.choice(['levy', 'cauchy', 'de'], p=[0.5, 0.3, 0.2])
                if op == 'levy':
                    levy = self._levy(self.dim) * g_scale
                    v = x_best + self.F * (pop[r1] - pop[r2]) + 0.2 * levy
                elif op == 'cauchy':
                    cauchy = self._cauchy(self.dim) * g_scale
                    v = x_best + self.F * (pop[r1] - pop[r2]) + 0.15 * cauchy
                else:
                    v = x_best + self.F * (pop[r3] + pop[r1] - 2 * pop[r2]) * g_scale

                cr_mask = self.rng.random(self.dim) < self.CR
                if not np.any(cr_mask):
                    cr_mask[self.rng.integers(0, self.dim)] = True
                trial = np.where(cr_mask, v, pop[i])
                f_trial = self._evaluate(trial, func)

                if f_trial < new_fit[i]:
                    new_pop[i] = trial
                    new_fit[i] = f_trial
                    self.success_F.append(self.F)
                    self.success_CR.append(self.CR)
                    if len(self.success_F) > 20:
                        self.success_F.pop(0)
                        self.success_CR.pop(0)

            pop = new_pop
            fitness = new_fit

            # Cliff-aware diversity restoration
            inf_count = np.sum(fitness == np.inf)
            if inf_count > self.pop_size // 2 or (self.best_f == prev_best and gen % 3 == 0):
                worst_idx = np.argsort(fitness)[-self.pop_size//4:]
                new_lhs = np.clip(_lhs(n_samples=self.pop_size//4, n_dim=self.dim) * 2.0 - 1.0, -1.0, 1.0)
                for j, idx in enumerate(worst_idx):
                    if self.evals < self.budget:
                        pop[idx] = new_lhs[j]
                        fitness[idx] = self._evaluate(pop[idx], func)
                prev_best = self.best_f
                stagnation = 0
            elif self.best_f < prev_best:
                prev_best = self.best_f
                stagnation = 0
            else:
                stagnation += 1

            if stagnation > self.stagnation_limit:
                stagnation = 0
                restart_idx = np.argsort(fitness)[self.pop_size//2:]
                new_lhs = np.clip(_lhs(n_samples=self.pop_size//2, n_dim=self.dim) * 2.0 - 1.0, -1.0, 1.0)
                for j, idx in enumerate(restart_idx):
                    if self.evals < self.budget:
                        pop[idx] = new_lhs[j]
                        fitness[idx] = self._evaluate(pop[idx], func)
                prev_best = self.best_f

        # Final elite refinement
        if self.evals < self.budget and grad_func is not None:
            valid_idx = np.where(fitness < np.inf)[0]
            top_idx = valid_idx[np.argsort(fitness[valid_idx])[:self.top_k]]
            for idx in top_idx:
                refined = self._gradient_adaptive_search(pop[idx], func, grad_func)
                f_refined = self._evaluate(refined, func)
                if f_refined < fitness[idx]:
                    pop[idx] = refined
                    fitness[idx] = f_refined

        return self.best_f, self.best_x
